def calculate_avg_marks(marks):
  # calculate the average marks
  totalMarks = 0
  for m in marks:
    totalMarks += m
  return totalMarks/len(marks)

def reverse_string(string, num): 
  for _ in range(num):
    string = string[::-1]
  return string 

